class Parent {
    public void Show() => Console.WriteLine("Parent Show");        // non-virtual
    public virtual void Speak() => Console.WriteLine("Parent Speak"); // virtual
}
class Child : Parent {
    public new void Show() => Console.WriteLine("Child Show");      // Hiding (Static Binding)
    public override void Speak() => Console.WriteLine("Child Speak");// Override (Dynamic Binding)
}
Parent p = new Child();
p.Show();  // "Parent Show"  (Variable type = Parent)
p.Speak(); // "Child Speak"  (Heap object   = Child)

