﻿namespace Relations
{
    public class Patient
    {
        public string Name { get; set; }

        public Doctor? TreatedBy { get; set; }

        public Patient(string name)
        {
            Name = name;
        }
    }

    public class Doctor
    {
        private int _count;

        public string Name { get; set; }

        public Patient[] Patients { get; private set; }

        public Doctor(string name, int capacity)
        {
            Name = name;
            Patients = new Patient[capacity];
            _count = 0;
        }


        public void Treat(Patient patient)
        {
            if (_count >= Patients.Length)
            {
                return;
            }

            Patients[_count] = patient;
            _count++;

            patient.TreatedBy = this;
        }

        public string PatientNames()
        {
            string result = string.Empty;

            for (int i = 0; i < _count; i++)
            {
                if (result.Length > 0)
                {
                    result += ", ";
                }

                result += Patients[i].Name;
            }

            return result;
        }
    }
}

