        public static void Swap(ref int a, ref int b)
        {
            int temp = a;
            a = b;
            b = temp;
        }

        public static void BubbleSort(int[] data)
        {
            for (int i = 0; i < data.Length - 1; i++)
            {
                bool swapped = false;

                for (int j = 0; j < data.Length - 1 - i; j++)
                {
                    if (data[j] > data[j + 1])
                    {
                        // An array element can be passed by ref - it is a real variable.
                        Swap(ref data[j], ref data[j + 1]);
                        swapped = true;
                    }
                }

                if (!swapped)
                {
                    break; // already sorted, stop early
                }
            }
        }

        // ------------------------------------------------------------------
        // Q2 - Rotate the array K positions to the LEFT.
        //      K may be bigger than the array length.
        // ------------------------------------------------------------------
        public static int[] RotateLeft(int[] source, int k)
        {
            int n = source.Length;
            int[] result = new int[n];

            if (n == 0)
            {
                return result;
            }

            k %= n;          // 6 % 4 -> 2
            if (k < 0)
            {
                k += n;      // supports a negative K as well
            }

            for (int i = 0; i < n; i++)
            {
                result[i] = source[(i + k) % n];
            }

            return result;
        }

