namespace CSharpBasicsLib.Functions
{
    /// <summary>
    /// Model answers for Questions 6 - 8 (User-Defined Functions and Parameters).
    /// </summary>
    public static class FunctionTasks
    {
        // ------------------------------------------------------------------
        // Q6 - Four results out of one call, using out parameters.
        //      Every out parameter MUST be assigned before the method returns.
        // ------------------------------------------------------------------
        public static void GetStats(int[] data, out int min, out int max, out int sum, out double avg)
        {
            if (data.Length == 0)
            {
                min = 0;
                max = 0;
                sum = 0;
                avg = 0;
                return;
            }

            min = data[0];
            max = data[0];
            sum = 0;

            foreach (int value in data)
            {
                if (value < min)
                {
                    min = value;
                }

                if (value > max)
                {
                    max = value;
                }

                sum += value;
            }

            avg = (double)sum / data.Length;
        }

        // ------------------------------------------------------------------
        // Q7 - params: a variable number of arguments.
        //      params must be the LAST parameter, and a method can have only one.
        // ------------------------------------------------------------------
        public static int Sum(params int[] numbers)
        {
            int total = 0;

            foreach (int number in numbers)
            {
                total += number;
            }

            return total;
        }

        public static double Average(params int[] numbers)
        {
            if (numbers.Length == 0)
            {
                return 0;   // calling with no arguments must not crash
            }

            return (double)Sum(numbers) / numbers.Length;
        }

        // ------------------------------------------------------------------
        // Q8 - Binary search, written twice: iterative and recursive.
        //      The array must already be sorted ascending.
        // ------------------------------------------------------------------
        public static int SearchIterative(int[] data, int target)
        {
            int low = 0;
            int high = data.Length - 1;

            while (low <= high)
            {
                int mid = low + (high - low) / 2;   // safer than (low + high) / 2

                if (data[mid] == target)
                {
                    return mid;
                }

                if (data[mid] < target)
                {
                    low = mid + 1;
                }
                else
                {
                    high = mid - 1;
                }
            }

            return -1;
        }

        public static int SearchRecursive(int[] data, int target, int low, int high)
        {
            if (low > high)
            {
                return -1;   // the base case that stops the recursion
            }

            int mid = low + (high - low) / 2;

            if (data[mid] == target)
            {
                return mid;
            }

            if (data[mid] < target)
            {
                return SearchRecursive(data, target, mid + 1, high);
            }

            return SearchRecursive(data, target, low, mid - 1);
        }
    }
}

