namespace CSharpBasicsLib.NullSafety
{
    /// <summary>
    /// Model answers for Questions 9 - 10 (Nullable Types and Null Operators).
    /// </summary>
    public static class NullTasks
    {
        // ------------------------------------------------------------------
        // Q9 - Return null instead of throwing when the divisor is 0.
        //      int? is just syntax sugar for Nullable<int>.
        // ------------------------------------------------------------------
        public static int? SafeDivide(int a, int b)
        {
            if (b == 0)
            {
                return null;
            }

            return a / b;
        }

        /// <summary>
        /// The caller prints without a single if statement:
        /// ?. stops the chain, ?? supplies the fallback text.
        /// </summary>
        public static string Describe(int? result)
        {
            return result?.ToString() ?? "Cannot divide by zero";
        }

        // ------------------------------------------------------------------
        // Q10 - A null-safe list of names.
        // ------------------------------------------------------------------
        public static void PrintLengths(string?[] names)
        {
            foreach (string? name in names)
            {
                // name?.Length short-circuits the WHOLE chain when name is null
                Console.WriteLine($"{name ?? "null"} -> {name?.Length.ToString() ?? "N/A"}");
            }
        }

        /// <summary>Replaces every null with "Unknown" using ??= .</summary>
        public static string[] FillUnknown(string?[] names)
        {
            string[] result = new string[names.Length];

            for (int i = 0; i < names.Length; i++)
            {
                string? current = names[i];
                current ??= "Unknown";      // assign only when it is null
                result[i] = current;
            }

            return result;
        }
    }
}

