    /// <summary>Live demo for the slides "Nullable Types" and "Null Operators".</summary>
    public static class NullSafetyDemo
    {
        public static void Run()
        {
            Console.WriteLine("=== 1. Nullable value type: int? is Nullable<int> ===");

            int? age = null;

            Console.WriteLine($"age.HasValue            -> {age.HasValue}");
            Console.WriteLine($"age.GetValueOrDefault() -> {age.GetValueOrDefault()}");
            Console.WriteLine("age.Value would throw InvalidOperationException right now.");

            age = 30;
            Console.WriteLine($"after age = 30, Value   -> {age.Value}");

            int back = (int)age;            // explicit cast in both directions
            Console.WriteLine($"cast back to int        -> {back}");

            Console.WriteLine();
            Console.WriteLine("=== 2. Nullable reference types are a COMPILER feature ===");

            string? nickname = null;

            Console.WriteLine("string? nickname = null;   -> no warning, it is annotated as nullable");
            Console.WriteLine("string  name = null;       -> warning CS8600 when <Nullable>enable</Nullable>");
            Console.WriteLine("Nothing changes at runtime - the IL is identical.");

            Console.WriteLine();
            Console.WriteLine("=== 3. ?.  null-conditional ===");

            int? length = nickname?.Length;
            Console.WriteLine($"nickname?.Length        -> {(length.HasValue ? length.Value.ToString() : "null")}");
            Console.WriteLine("The whole chain stops and returns null instead of throwing.");

            Console.WriteLine();
            Console.WriteLine("=== 4. ??  null-coalescing ===");

            string display = nickname ?? "Guest";
            Console.WriteLine($"nickname ?? \"Guest\"     -> {display}");

            Console.WriteLine();
            Console.WriteLine("=== 5. ??=  null-coalescing assignment ===");

            nickname ??= "Guest";
            Console.WriteLine($"after nickname ??= ...  -> {nickname}");

            nickname ??= "Ahmed";
            Console.WriteLine($"assigning again         -> {nickname}   (unchanged - it is no longer null)");

            Console.WriteLine();
            Console.WriteLine("=== 6. !  null-forgiving ===");

            string? maybe = GetMaybe();

            Console.WriteLine($"maybe!.Length           -> {maybe!.Length}");
            Console.WriteLine("The ! only silences the compiler. It does NOT add a runtime check -");
            Console.WriteLine("if the value really were null, this line would still throw.");
        }

        private static string? GetMaybe()
        {
            return "Route";
        }
    }
}

