namespace Workshop02.ConsoleApp.Demos
{
    /// <summary>Live demo for the slide "Class vs Struct vs Record vs Interface".</summary>
    public static class TypesDemo
    {
        public struct PointStruct
        {
            public int X;
            public int Y;
        }

        public class PointClass
        {
            public int X;
            public int Y;
        }

        public record PointRecord(int X, int Y);

        public static void Run()
        {
            Console.WriteLine("=== 1. Assignment: copy or share? ===");

            PointStruct s1 = new PointStruct { X = 1, Y = 1 };
            PointStruct s2 = s1;          // full copy
            s2.X = 100;

            Console.WriteLine($"struct : s1.X = {s1.X}   s2.X = {s2.X}   -> the struct was COPIED");

            PointClass c1 = new PointClass { X = 1, Y = 1 };
            PointClass c2 = c1;           // copy of the reference only
            c2.X = 100;

            Console.WriteLine($"class  : c1.X = {c1.X}   c2.X = {c2.X}   -> both names point at ONE object");

            Console.WriteLine();
            Console.WriteLine("=== 2. Equality ===");

            PointStruct sa = new PointStruct { X = 1, Y = 2 };
            PointStruct sb = new PointStruct { X = 1, Y = 2 };
            Console.WriteLine($"struct : sa.Equals(sb) -> {sa.Equals(sb)}    (value equality, field by field)");

            PointClass ca = new PointClass { X = 1, Y = 2 };
            PointClass cb = new PointClass { X = 1, Y = 2 };
            Console.WriteLine($"class  : ca.Equals(cb) -> {ca.Equals(cb)}   (reference equality - two objects)");

            PointRecord ra = new PointRecord(1, 2);
            PointRecord rb = new PointRecord(1, 2);
            Console.WriteLine($"record : ra == rb      -> {ra == rb}    (value equality, generated for you)");

            Console.WriteLine();
            Console.WriteLine("=== 3. ToString() ===");

            Console.WriteLine($"class  -> {ca}");
            Console.WriteLine($"record -> {rb}");
            Console.WriteLine("A record also generates ToString(), GetHashCode() and a 'with' expression.");

            Console.WriteLine();
            Console.WriteLine("=== 4. Non-destructive copy: 'with' ===");

            PointRecord moved = ra with { X = 99 };
            Console.WriteLine($"ra    -> {ra}");
            Console.WriteLine($"moved -> {moved}");

            Console.WriteLine();
            Console.WriteLine("=== 5. Null ===");

            PointClass? nullableClass = null;
            Console.WriteLine($"a class variable can be null      -> {(nullableClass is null)}");
            Console.WriteLine("a struct variable can NOT be null  -> you must write PointStruct? for that");

            PointStruct? nullableStruct = null;
            Console.WriteLine($"PointStruct? nullableStruct = null -> HasValue = {nullableStruct.HasValue}");
        }
    }
}

