        // ------------------------------------------------------------------
        public static void SwapByValue(int a, int b)
        {
            int temp = a;
            a = b;
            b = temp;
            // a and b are copies on the Stack. The caller never sees this.
        }

        public static void SwapByRef(ref int a, ref int b)
        {
            int temp = a;
            a = b;
            b = temp;
            // a and b ARE the caller's variables.
        }

        // ------------------------------------------------------------------
        // Q15 - Changing the object vs changing WHICH object.
        // ------------------------------------------------------------------
        public static void ChangeElement(int[] data)
        {
            data[0] = 999;
            // Works. The copy is the reference, and it points at the caller's array.
        }

        public static void ReplaceArray(int[] data)
        {
            data = new int[] { 1, 1, 1 };
            // Lost. Only the local copy of the reference now points somewhere else.
        }

        public static void ReplaceArrayByRef(ref int[] data)
        {
            data = new int[] { 1, 1, 1 };
            // Works. ref means "the caller's variable", so the caller re-points too.
        }

        // ------------------------------------------------------------------
