        //       Three distinct names - no overloading is used here.
        // ------------------------------------------------------------------
        public static void ModifyBoxByValue(Box b)
        {
            b.Value = 100;   // b is a full copy of the struct
        }

        public static void ModifyBoxByRef(ref Box b)
        {
            b.Value = 100;   // b is the caller's struct
        }

        public static void ModifyBag(Bag g)
        {
            g.Value = 100;   // g is a copy of the reference to the same object
        }

        // ------------------------------------------------------------------
