namespace CSharpBasicsLib.Types
{
    // ======================================================================
    // Q11 - Enum + switch expression with relational patterns
    // ======================================================================
    public enum Grade
    {
        F,   // 0
        D,   // 1
        C,   // 2
        B,   // 3
        A    // 4
    }

    public static class GradeCalculator
    {
        public static bool IsValidMark(int mark)
        {
            return mark >= 0 && mark <= 100;
        }

        public static Grade FromMark(int mark)
        {
            return mark switch
            {
                >= 90 => Grade.A,
                >= 80 => Grade.B,
                >= 70 => Grade.C,
                >= 60 => Grade.D,
                _     => Grade.F
            };
        }
    }

    // ======================================================================
    // Q12 - [Flags] enum: one variable holding many options
    // ======================================================================
    [Flags]
    public enum Permission
    {
        None    = 0,   // 0000
        Read    = 1,   // 0001
        Write   = 2,   // 0010
        Delete  = 4,   // 0100
        Execute = 8    // 1000
    }

    public static class PermissionService
    {
        /// <summary>Combines the given names with the bitwise OR operator.</summary>
        public static Permission Grant(string[] names)
        {
            Permission result = Permission.None;

            foreach (string name in names)
            {
                // TryParse never throws - Parse would
                if (Enum.TryParse(name, true, out Permission single) &&
                    Enum.IsDefined(typeof(Permission), single))
                {
                    result |= single;
                }
            }

            return result;
        }

        public static bool Has(Permission current, Permission wanted)
        {
            return current.HasFlag(wanted);
        }

        public static Permission Revoke(Permission current, Permission unwanted)
        {
            return current & ~unwanted;
        }
    }

    // ======================================================================
    // Q13 - A struct is a VALUE type: assigning it copies it
    // ======================================================================
    public struct Point
    {
        public int X;
        public int Y;

        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }

        public double DistanceTo(Point other)
        {
            int dx = X - other.X;
            int dy = Y - other.Y;

            return Math.Sqrt((dx * dx) + (dy * dy));
        }

        public override string ToString()
        {
            return $"({X}, {Y})";
        }
    }
}
