namespace Workshop02.ConsoleApp.Demos
{
    /// <summary>Live demo for the slides "Array Class &amp; Array Methods" and "1D / 2D / Jagged".</summary>
    public static class ArrayDemo
    {
        public static void Run()
        {
            Console.WriteLine("=== 1. Array class helpers ===");

            int[] numbers = { 40, 10, 30, 20, 50 };

            Array.Sort(numbers);
            Console.WriteLine($"Sort()          -> {string.Join(" ", numbers)}");

            Array.Reverse(numbers);
            Console.WriteLine($"Reverse()       -> {string.Join(" ", numbers)}");

            Console.WriteLine($"IndexOf(30)     -> {Array.IndexOf(numbers, 30)}");

            Array.Sort(numbers);
            Console.WriteLine($"BinarySearch(30)-> {Array.BinarySearch(numbers, 30)}   (array must be sorted first)");

            int[] filled = new int[5];
            Array.Fill(filled, 7);
            Console.WriteLine($"Fill(7)         -> {string.Join(" ", filled)}");

            Console.WriteLine();
            Console.WriteLine("=== 2. Resize does NOT resize ===");

            int[] original = { 1, 2, 3 };
            int[] alias = original;                 // both names, one array

            Array.Resize(ref original, 5);          // note the ref - a NEW array is created

            Console.WriteLine($"original.Length -> {original.Length}   (re-pointed to a new array)");
            Console.WriteLine($"alias.Length    -> {alias.Length}   (still the OLD array)");
            Console.WriteLine("Resize creates a new array and re-points your variable. That is why it needs ref.");

            Console.WriteLine();
            Console.WriteLine("=== 3. Clone is a SHALLOW copy ===");

            int[][] rows = new int[2][];
            rows[0] = new int[] { 1, 2 };
            rows[1] = new int[] { 3, 4 };

            int[][] cloned = (int[][])rows.Clone();
            cloned[0][0] = 999;                     // change through the clone

            Console.WriteLine($"rows[0][0]      -> {rows[0][0]}   (the original changed too!)");
            Console.WriteLine("Clone copied the outer array only - both outer arrays point at the same rows.");

            Console.WriteLine();
            Console.WriteLine("=== 4. 1D vs 2D vs Jagged ===");

            int[] oneD = new int[5];
            oneD[2] = 30;
            Console.WriteLine($"1D     : Length={oneD.Length}  Rank={oneD.Rank}");

            int[,] grid = new int[3, 4];
            grid[1, 2] = 7;
            Console.WriteLine($"2D     : GetLength(0)={grid.GetLength(0)}  GetLength(1)={grid.GetLength(1)}  Rank={grid.Rank}");
            Console.WriteLine("         One single block on the Heap - every row has the same length.");

            int[][] jagged = new int[3][];
            jagged[0] = new int[4];
            jagged[1] = new int[2];
            jagged[2] = new int[5];
            Console.WriteLine($"Jagged : rows={jagged.Length}  row0={jagged[0].Length}  row1={jagged[1].Length}  row2={jagged[2].Length}");
            Console.WriteLine("         One outer array of references - each row is a separate array object.");
        }
    }
}
