using CSharpBasicsLib.Types;

namespace Workshop02.ConsoleApp.Demos
{
    /// <summary>Live demo for the slides "Enums Deep Dive" and "[Flags] Enums".</summary>
    public static class EnumsDemo
    {
        public enum Status
        {
            Pending,        // 0
            Approved = 10,  // 10
            Shipped         // 11 - values continue from the last one you set
        }

        public enum Level : byte
        {
            Low,
            High
        }

        public static void Run()
        {
            Console.WriteLine("=== 1. Underlying values ===");

            Console.WriteLine($"(int)Status.Pending  -> {(int)Status.Pending}");
            Console.WriteLine($"(int)Status.Approved -> {(int)Status.Approved}");
            Console.WriteLine($"(int)Status.Shipped  -> {(int)Status.Shipped}   (continues from 10)");
            Console.WriteLine($"underlying type of Level -> {Enum.GetUnderlyingType(typeof(Level)).Name}");

            Console.WriteLine();
            Console.WriteLine("=== 2. Conversions are explicit in both directions ===");

            Status fromNumber = (Status)10;
            Console.WriteLine($"(Status)10           -> {fromNumber}");

            Status weird = (Status)99;
            Console.WriteLine($"(Status)99           -> {weird}   (a number with no name - still legal!)");
            Console.WriteLine($"Enum.IsDefined(99)   -> {Enum.IsDefined(typeof(Status), 99)}   <- always validate external input");

            Console.WriteLine();
            Console.WriteLine("=== 3. Parse vs TryParse ===");

            Status parsed = Enum.Parse<Status>("Shipped");
            Console.WriteLine($"Enum.Parse(\"Shipped\") -> {parsed}");

            bool ok = Enum.TryParse("Bad", out Status result);
            Console.WriteLine($"Enum.TryParse(\"Bad\")  -> ok={ok}, result={result}   (Parse would have thrown)");

            Console.WriteLine();
            Console.WriteLine("=== 4. Listing every member ===");

            foreach (Status value in Enum.GetValues<Status>())
            {
                Console.WriteLine($"   {value,-10} = {(int)value}");
            }

            Console.WriteLine();
            Console.WriteLine("=== 5. Enums pair naturally with switch expressions ===");

            Console.WriteLine($"Describe(Status.Pending)  -> {Describe(Status.Pending)}");
            Console.WriteLine($"Describe(Status.Shipped)  -> {Describe(Status.Shipped)}");

            Console.WriteLine();
            Console.WriteLine("=== 6. [Flags]: one variable, many options ===");

            Permission current = Permission.Read | Permission.Write;
            Console.WriteLine($"Read | Write             -> {current}  (value = {(int)current})");

            Console.WriteLine($"HasFlag(Write)           -> {current.HasFlag(Permission.Write)}");
            Console.WriteLine($"HasFlag(Delete)          -> {current.HasFlag(Permission.Delete)}");

            current |= Permission.Delete;                  // add
            Console.WriteLine($"after |= Delete          -> {current}  (value = {(int)current})");

            current &= ~Permission.Write;                  // remove
            Console.WriteLine($"after &= ~Write          -> {current}  (value = {(int)current})");

            Console.WriteLine();
            Console.WriteLine("Without [Flags] the last line would just print the number 5.");
            Console.WriteLine("Values must be powers of two, and None = 0 is the empty state.");
        }

        private static string Describe(Status status)
        {
            return status switch
            {
                Status.Pending  => "waiting for review",
                Status.Approved => "ready to ship",
                Status.Shipped  => "on the way",
                _               => "unknown"
            };
        }
    }
}
