namespace Workshop02.ConsoleApp.Demos
{
    /// <summary>Live demo for the slides "Parameter Passing" and "Value Type vs Reference Type".</summary>
    public static class ParameterPassingDemo
    {
        // A deliberately large struct so "in" has a real reason to exist.
        public struct BigStruct
        {
            public double A, B, C, D, E, F, G, H;
        }

        public static void Run()
        {
            Console.WriteLine("=== 1. No modifier: the method works on a COPY ===");

            int x = 5;
            ChangeByValue(x);
            Console.WriteLine($"x after ChangeByValue -> {x}   (unchanged)");

            Console.WriteLine();
            Console.WriteLine("=== 2. ref: the method works on the CALLER'S variable ===");

            int y = 5;
            ChangeByRef(ref y);
            Console.WriteLine($"y after ChangeByRef   -> {y}   (changed)");
            Console.WriteLine("A ref argument must already be initialized before the call.");

            Console.WriteLine();
            Console.WriteLine("=== 3. out: for returning extra results ===");

            GetCircle(2.0, out double area, out double circumference);
            Console.WriteLine($"area          -> {area:F2}");
            Console.WriteLine($"circumference -> {circumference:F2}");
            Console.WriteLine("Every out parameter must be assigned before the method returns.");

            Console.WriteLine();
            Console.WriteLine("=== 4. in: pass a big struct without copying it ===");

            BigStruct big = new BigStruct { A = 1, B = 2 };
            ShowReadOnly(in big);
            Console.WriteLine("Inside the method the parameter is readonly - assigning to it will not compile.");

            Console.WriteLine();
            Console.WriteLine("=== 5. params: a variable number of arguments ===");

            Console.WriteLine($"Total()          -> {Total()}");
            Console.WriteLine($"Total(5)         -> {Total(5)}");
            Console.WriteLine($"Total(5, 10, 15) -> {Total(5, 10, 15)}");
            Console.WriteLine("params must be the LAST parameter, and a method can have only one.");

            Console.WriteLine();
            Console.WriteLine("=== 6. Value type vs reference type - the whole point ===");

            int number = 5;
            TryToChangeNumber(number);
            Console.WriteLine($"int after the call     -> {number}   (a copy of the VALUE was passed)");

            int[] data = { 5, 6, 7 };
            TryToChangeArray(data);
            Console.WriteLine($"array after the call   -> {string.Join(" ", data)}   (element changed, array not replaced)");
            Console.WriteLine();
            Console.WriteLine("Without ref, C# always copies the argument.");
            Console.WriteLine("For a reference type, what gets copied is the reference - not the object.");
        }

        private static void ChangeByValue(int n)
        {
            n = 99;
        }

        private static void ChangeByRef(ref int n)
