namespace ArraysEnumsLib.ArrayExamples
{
    /// <summary>
    /// Model answers for Questions 4 - 5.
    /// Not a single Array class method is used here - that is the point.
    /// </summary>
    public static class ArrayExampleTasks
    {
        // ------------------------------------------------------------------
        // Q4a - Reverse using two pointers walking toward each other.
        // ------------------------------------------------------------------
        public static void ReverseInPlace(int[] data)
        {
            int left = 0;
            int right = data.Length - 1;

            while (left < right)
            {
                int temp = data[left];
                data[left] = data[right];
                data[right] = temp;

                left++;
                right--;
            }
        }

        // ------------------------------------------------------------------
        // Q4b - Max. Start from data[0], NEVER from 0.
        //       Starting from 0 returns the wrong answer for all-negative input.
        // ------------------------------------------------------------------
        public static int MaxValue(int[] data)
        {
            int max = data[0];

            for (int i = 1; i < data.Length; i++)
            {
                if (data[i] > max)
                {
                    max = data[i];
                }
            }

            return max;
        }

        // ------------------------------------------------------------------
        // Q4c - Sum.
        // ------------------------------------------------------------------
        public static int SumAll(int[] data)
        {
            int sum = 0;

            foreach (int value in data)
            {
                sum += value;
            }

            return sum;
        }

        // ------------------------------------------------------------------
        // Q5 - Push every 0 to the end, keeping the order of the rest.
        //      One read index, one write index, one pass, no second array.
        // ------------------------------------------------------------------
        public static void MoveZerosToEnd(int[] data)
        {
            int write = 0;

            for (int read = 0; read < data.Length; read++)
            {
                if (data[read] != 0)
                {
                    data[write] = data[read];
                    write++;
                }
            }

            while (write < data.Length)
            {
                data[write] = 0;
                write++;
            }
        }
    }
}

[Workshop03Demo/ArraysEnumsLib/ArrayFunctions/ArrayFunctionTasks.cs] using System;

namespace ArraysEnumsLib.ArrayFunctions
{
    /// <summary>
    /// Model answers for Questions 1 - 3.
    /// These three MUST use the Array class methods.
    /// </summary>
    public static class ArrayFunctionTasks
    {
        // ------------------------------------------------------------------
        // Q1 - IndexOf / LastIndexOf on the original array, then Sort + Reverse.
        // ------------------------------------------------------------------
        public static void ShowToolbox(int[] data, int target)
        {
            Console.WriteLine($"IndexOf: {Array.IndexOf(data, target)}");
            Console.WriteLine($"LastIndexOf: {Array.LastIndexOf(data, target)}");

            // Work on a copy so the caller's array keeps its original order.
            int[] sorted = new int[data.Length];
            Array.Copy(data, sorted, data.Length);

            Array.Sort(sorted);
            Console.WriteLine($"Sorted: {string.Join(" ", sorted)}");

            Array.Reverse(sorted);           // there is no Array.SortDescending
            Console.WriteLine($"Descending: {string.Join(" ", sorted)}");
        }

        // ------------------------------------------------------------------
        // Q2 - Resize, then Fill only the NEW slots with -1.
        // ------------------------------------------------------------------
        public static int[] ResizeAndFill(int[] data, int newSize)
        {
            int oldSize = data.Length;

            int[] result = data;                    // Resize needs a variable it can re-point
            Array.Resize(ref result, newSize);      // builds a NEW array, copies the old values in

            if (newSize > oldSize)
            {
                // Fill(array, value, startIndex, count) - only the slots that were added
                Array.Fill(result, -1, oldSize, newSize - oldSize);
            }

            return result;
        }

        // ------------------------------------------------------------------
        // Q3 - Extract a slice with Array.Copy, or report an invalid range.
        // ------------------------------------------------------------------
        public static bool TryGetSlice(int[] data, int start, int count, out int[] slice)
        {
            slice = new int[0];

            if (start < 0 || count < 0 || start + count > data.Length)
            {
                return false;                       // validate BEFORE calling Array.Copy
            }

            slice = new int[count];
            Array.Copy(data, start, slice, 0, count);

            return true;
        }
    }
}

[Workshop03Demo/ArraysEnumsLib/Jagged/JaggedTasks.cs] using System;

namespace ArraysEnumsLib.Jagged
{
    /// <summary>
    /// Model answers for Questions 6 - 7 (Jagged Arrays).
    /// The golden rule: the inner loop uses rows[i].Length, never rows.Length.
    /// </summary>
    public static class JaggedTasks
    {



        // ------------------------------------------------------------------
        // Q6 - Print every row with its length and sum, then the grand total.
        // ------------------------------------------------------------------
        // for every row print 
        // - row index
        // - length 
        // - numbers
        // - sum 

        //total sum of all numbers 

        public static void PrintRows(int[][] rows)
        {
            int total = 0;

            for (int i = 0; i < rows.Length; i++)
            {
                int sum = SumRow(rows[i]);
                total += sum;

                Console.WriteLine($"Row {i} ({rows[i].Length}): {string.Join(" ", rows[i])} | Sum = {sum}");
            }

            Console.WriteLine($"Total = {total}");
        }

        public static int SumRow(int[] row)
        {
            int sum = 0;

            for (int j = 0; j < row.Length; j++)
            {
                sum += row[j];
            }

            return sum;
        }

        // ------------------------------------------------------------------
        // Q7 - One row of marks per student. Rows have different lengths,
        //      which is exactly what a 2D array cannot do.
        // ------------------------------------------------------------------
        public static double AverageOf(int[] marks)
        {
            if (marks.Length == 0)
            {
                return 0;
            }

            return (double)SumRow(marks) / marks.Length;
        }

        public static void PrintAverages(string[] names, int[][] marks)
        {
            for (int i = 0; i < names.Length; i++)
            {
                Console.WriteLine($"{names[i]}: {AverageOf(marks[i]):F2}");
            }
        }

        public static string TopStudent(string[] names, int[][] marks)
        {
            string top = names[0];
            double best = AverageOf(marks[0]);

            for (int i = 1; i < names.Length; i++)
            {
                double average = AverageOf(marks[i]);

                if (average > best)
                {
                    best = average;
                    top = names[i];
                }
            }

            return top;
        }
    }
}

[Workshop03Demo/ArraysEnumsLib/Permissions/PermissionTasks.cs] using System;

namespace ArraysEnumsLib.Permissions
{
    /// <summary>
    /// Every member owns a different bit, so combining them can never collide.
    /// [Flags] does not change the values - it changes what ToString() prints.
    /// </summary>
    [Flags]
    public enum Permission
    {
        None    = 0,   // 0000
        Read    = 1,   // 0001
        Write   = 2,   // 0010
        Delete  = 4,   // 0100
        Execute = 8    // 1000
    }

    /// <summary>Model answer for Question 8.</summary>
    public static class PermissionTasks
    {
        /// <summary>Turns one name into a Permission. Returns None when the name is unknown.</summary>
        public static Permission ParseOne(string name)
        {
            if (Enum.TryParse(name, true, out Permission value) &&
                Enum.IsDefined(typeof(Permission), value))
            {
                return value;
            }

            return Permission.None;
        }

        /// <summary>Combines many names with the bitwise OR operator.</summary>
        public static Permission Combine(string[] names)
        {
            Permission result = Permission.None;

            foreach (string name in names)
            {
                result |= ParseOne(name);
            }

            return result;
        }

        public static Permission Add(Permission current, Permission extra)
        {
            return current | extra;          // set the bit
        }

        public static Permission Revoke(Permission current, Permission unwanted)
        {
            return current & ~unwanted;      // clear the bit
        }

        public static bool Has(Permission current, Permission wanted)
        {
            return current.HasFlag(wanted);
        }

        /// <summary>"Read, Delete (5)" - the enum name plus its numeric value.</summary>
        public static string Describe(Permission value)
        {
            return $"{value} ({(int)value})";
        }

        /// <summary>Lists every granted member. None is skipped - HasFlag(None) is always true.</summary>
        public static string ListGranted(Permission value)
        {
            string result = string.Empty;

            foreach (Permission single in Enum.GetValues<Permission>())
            {
                if (single == Permission.None)
                {
                    continue;
                }

                if (value.HasFlag(single))
                {
                    if (result.Length > 0)
                    {
                        result += ", ";
                    }

                    result += single.ToString();
                }
            }

            if (result.Length == 0)
            {
                return "None";
            }

            return result;
        }
    }
}

[Workshop03Demo/README.md] # Arrays & Enums — Workshop 03 Demo

Companion code for `Week04_Basics.pptx` and `Week04_Questions_Bank.pptx` (.NET Track).

Target framework: **net8.0** · `ImplicitUsings` **disabled** (every `using` is written out) · `Nullable` **enabled**.

## Structure

```
Workshop03Demo.sln
├── ArraysEnumsLib/                        class library
│   ├── ArrayFunctions/ArrayFunctionTasks.cs   Q1 – Q3   (must use the Array class)
│   ├── ArrayExamples/ArrayExampleTasks.cs     Q4 – Q5   (must NOT use the Array class)
│   ├── Jagged/JaggedTasks.cs                  Q6 – Q7
│   └── Permissions/PermissionTasks.cs         Q8        ([Flags] enum lives here)
└── Workshop03.ConsoleApp/
    ├── Program.cs                         menu
    ├── AnswerKey.cs                       runs all 8 questions with the slide's sample data
    └── Demos/
        ├── ArrayFunctionsDemo.cs
        ├── ArrayExamplesDemo.cs
        ├── JaggedArrayDemo.cs
        └── PermissionDemo.cs
```

## Run it

```bash
dotnet run --project Workshop03.ConsoleApp
```

Or open `Workshop03Demo.sln` in Visual Studio, set **Workshop03.ConsoleApp** as the startup project, and press F5.

## Menu

| Option | What it shows | Slide |
|---|---|---|
| 1 | the slide example line by line, `Copy` vs `CopyTo`, why `Resize` needs `ref` | Array Functions · Copy / CopyTo / Resize |
| 2 | `for` vs `foreach`, reverse with two pointers, max without `Array.Sort`, move zeros | Walking an Array · More Examples |
| 3 | the three ways to build `int[][]`, the null-row trap, jagged vs 2D syntax, marks per student | the three Jagged slides |
| 4 | the bit table, combine / check / add / revoke, listing granted flags, roles | the three Permission slides |
| 5 | every question's expected output | Questions Bank |

## Notes for the session

* **No overloading, no interfaces, no lambdas** — everything here uses only what the students have covered.
* Two lines are commented out on purpose, to uncomment live so the class sees the error:
  * `ArrayExamplesDemo` — assigning to a `foreach` loop variable.
  * In `JaggedArrayDemo`, call `.Length` on the row that was never created and show the `NullReferenceException`.
* The `Resize` demo is the one worth spending time on: keep a second variable pointing at the array, resize through the first one, and print both lengths.
* `CultureInfo.InvariantCulture` is set in `Main` so averages print as `80.00`, not `80,00`.

