[Workshop03Demo/Workshop03.ConsoleApp/Demos/ArrayFunctionsDemo.cs] using System;

namespace Workshop03.ConsoleApp.Demos
{
    /// <summary>Live demo for the slides "Array Functions" and "Copy / CopyTo / Resize".</summary>
    public static class ArrayFunctionsDemo
    {
        public static void Run()
        {
            Console.WriteLine("=== 1. The slide example, line by line ===");

            int[] marks = { 70, 40, 90, 55, 90 };

            Console.WriteLine($"IndexOf(90)     -> {Array.IndexOf(marks, 90)}");
            Console.WriteLine($"LastIndexOf(90) -> {Array.LastIndexOf(marks, 90)}");

            Array.Sort(marks);
            Console.WriteLine($"after Sort      -> {string.Join(" ", marks)}");

            Console.WriteLine($"BinarySearch(55)-> {Array.BinarySearch(marks, 55)}   (only valid on a sorted array)");

            Array.Reverse(marks);
            Console.WriteLine($"after Reverse   -> {string.Join(" ", marks)}");

            Array.Resize(ref marks, 7);
            Array.Fill(marks, -1, 5, 2);
            Console.WriteLine($"Resize + Fill   -> {string.Join(" ", marks)}");

            Console.WriteLine();
            Console.WriteLine("=== 2. Copy vs CopyTo ===");

            int[] source = { 1, 2, 3, 4, 5 };

            int[] target = new int[5];
            Array.Copy(source, 2, target, 0, 3);        // a slice from the middle
            Console.WriteLine($"Array.Copy(src, 2, dest, 0, 3) -> {string.Join(" ", target)}");

            int[] target2 = new int[5];
            source.CopyTo(target2, 0);                  // the whole thing, written the other way round
            Console.WriteLine($"source.CopyTo(dest, 0)         -> {string.Join(" ", target2)}");

            Console.WriteLine();
            Console.WriteLine("Both of them need a destination array that already exists and is big enough.");
            Console.WriteLine("Make target2 an int[3] and CopyTo throws ArgumentException.");

            Console.WriteLine();
            Console.WriteLine("=== 3. Resize does not resize ===");

            int[] original = { 1, 2, 3 };
            int[] alias = original;                     // two names, one array

            Array.Resize(ref original, 5);              // builds a NEW array and re-points 'original'

            Console.WriteLine($"original -> {string.Join(" ", original)}   (Length {original.Length})");
            Console.WriteLine($"alias    -> {string.Join(" ", alias)}   (Length {alias.Length})");
            Console.WriteLine();
            Console.WriteLine("'alias' still points at the old array - it never heard about the resize.");
            Console.WriteLine("That is exactly why Array.Resize takes its parameter by ref.");
        }
    }
}

