namespace ArraysEnumsLib.Jagged
{
    /// <summary>
    /// Model answers for Questions 6 - 7 (Jagged Arrays).
    /// The golden rule: the inner loop uses rows[i].Length, never rows.Length.
    /// </summary>
    public static class JaggedTasks
    {



        // ------------------------------------------------------------------
        // Q6 - Print every row with its length and sum, then the grand total.
        // ------------------------------------------------------------------
        // for every row print 
        // - row index
        // - length 
        // - numbers
        // - sum 

        //total sum of all numbers 

        public static void PrintRows(int[][] rows)
        {
            int total = 0;

            for (int i = 0; i < rows.Length; i++)
            {
                int sum = SumRow(rows[i]);
                total += sum;

                Console.WriteLine($"Row {i} ({rows[i].Length}): {string.Join(" ", rows[i])} | Sum = {sum}");
            }

            Console.WriteLine($"Total = {total}");
        }

        public static int SumRow(int[] row)
        {
            int sum = 0;

            for (int j = 0; j < row.Length; j++)
            {
                sum += row[j];
            }

            return sum;
        }

        // ------------------------------------------------------------------
        // Q7 - One row of marks per student. Rows have different lengths,
        //      which is exactly what a 2D array cannot do.
        // ------------------------------------------------------------------
        public static double AverageOf(int[] marks)
        {
            if (marks.Length == 0)
            {
                return 0;
            }

            return (double)SumRow(marks) / marks.Length;
        }

        public static void PrintAverages(string[] names, int[][] marks)
        {
            for (int i = 0; i < names.Length; i++)
            {
                Console.WriteLine($"{names[i]}: {AverageOf(marks[i]):F2}");
            }
        }

        public static string TopStudent(string[] names, int[][] marks)
        {
            string top = names[0];
            double best = AverageOf(marks[0]);

            for (int i = 1; i < names.Length; i++)
            {
                double average = AverageOf(marks[i]);

                if (average > best)
                {
                    best = average;
                    top = names[i];
                }
            }

            return top;
        }
    }
}
