namespace ArraysEnumsLib.Permissions
{
    /// <summary>
    /// Every member owns a different bit, so combining them can never collide.
    /// [Flags] does not change the values - it changes what ToString() prints.
    /// </summary>
    [Flags]
    public enum Permission
    {
        None    = 0,   // 0000
        Read    = 1,   // 0001
        Write   = 2,   // 0010
        Delete  = 4,   // 0100
        Execute = 8    // 1000
    }

    /// <summary>Model answer for Question 8.</summary>
    public static class PermissionTasks
    {
        /// <summary>Turns one name into a Permission. Returns None when the name is unknown.</summary>
        public static Permission ParseOne(string name)
        {
            if (Enum.TryParse(name, true, out Permission value) &&
                Enum.IsDefined(typeof(Permission), value))
            {
                return value;
            }

            return Permission.None;
        }

        /// <summary>Combines many names with the bitwise OR operator.</summary>
        public static Permission Combine(string[] names)
        {
            Permission result = Permission.None;

            foreach (string name in names)
            {
                result |= ParseOne(name);
            }

            return result;
        }

        public static Permission Add(Permission current, Permission extra)
        {
            return current | extra;          // set the bit
        }

        public static Permission Revoke(Permission current, Permission unwanted)
        {
            return current & ~unwanted;      // clear the bit
        }

        public static bool Has(Permission current, Permission wanted)
        {
            return current.HasFlag(wanted);
        }

        /// <summary>"Read, Delete (5)" - the enum name plus its numeric value.</summary>
        public static string Describe(Permission value)
        {
            return $"{value} ({(int)value})";
        }

        /// <summary>Lists every granted member. None is skipped - HasFlag(None) is always true.</summary>
        public static string ListGranted(Permission value)
        {
            string result = string.Empty;

            foreach (Permission single in Enum.GetValues<Permission>())
            {
                if (single == Permission.None)
                {
                    continue;
                }

                if (value.HasFlag(single))
                {
                    if (result.Length > 0)
                    {
                        result += ", ";
                    }

                    result += single.ToString();
                }
            }

            if (result.Length == 0)
            {
                return "None";
            }

            return result;
        }
    }
}
