        {
            Console.WriteLine("=== 1. for - you control the index, you can change elements ===");

            int[] data = { 1, 2, 3, 4 };

            for (int i = 0; i < data.Length; i++)
            {
                data[i] = data[i] * 2;
            }

            Console.WriteLine($"after the for loop -> {string.Join(" ", data)}");

            Console.WriteLine();
            Console.WriteLine("=== 2. foreach - read only, no index ===");

            foreach (int value in data)
            {
                // value = value * 2;   <- uncomment: the loop variable is read-only
                Console.Write(value + " ");
            }

            Console.WriteLine();
            Console.WriteLine("Rule: reading only -> foreach. Changing elements or needing the index -> for.");

            Console.WriteLine();
            Console.WriteLine("=== 3. Reverse in place (two pointers) ===");

            int[] a = { 3, 8, 1, 9, 4 };
            ArrayExampleTasks.ReverseInPlace(a);
            Console.WriteLine($"{string.Join(" ", a)}");

            Console.WriteLine();
            Console.WriteLine("=== 4. Max without Array.Sort ===");

            Console.WriteLine($"Max of  3 8 1 9 4    -> {ArrayExampleTasks.MaxValue(new[] { 3, 8, 1, 9, 4 })}");
            Console.WriteLine($"Max of -5 -1 -9      -> {ArrayExampleTasks.MaxValue(new[] { -5, -1, -9 })}   <- starting max at 0 would print 0");

            Console.WriteLine();
            Console.WriteLine("=== 5. Move every zero to the end ===");

            int[] withZeros = { 0, 3, 0, 5, 7, 0 };
            ArrayExampleTasks.MoveZerosToEnd(withZeros);
            Console.WriteLine($"{string.Join(" ", withZeros)}   (order of the other values is kept)");

            Console.WriteLine();
            Console.WriteLine("=== 6. Sum ===");

