namespace Workshop03.ConsoleApp.Demos
{
    /// <summary>Live demo for the three "Jagged Arrays" slides.</summary>
    public static class JaggedArrayDemo
    {
        public static void Run()
        {
            Console.WriteLine("=== 1. Three ways to build a jagged array ===");

            // 1 - row by row
            int[][] wayOne = new int[3][];
            wayOne[0] = new int[4];
            wayOne[1] = new int[2];
            wayOne[2] = new int[5];
            Console.WriteLine($"way 1  rows={wayOne.Length}  lengths = {wayOne[0].Length} {wayOne[1].Length} {wayOne[2].Length}");

            // 2 - created and filled together
            int[][] wayTwo = new int[3][];
            wayTwo[0] = new int[] { 1, 2, 3, 4 };
            wayTwo[1] = new int[] { 5, 6 };
            wayTwo[2] = new int[] { 7, 8, 9 };
            Console.WriteLine($"way 2  row0 = {string.Join(" ", wayTwo[0])}");

            // 3 - all at once
            int[][] wayThree =
            {
                new int[] { 1, 2, 3, 4 },
                new int[] { 5, 6 },
                new int[] { 7, 8, 9 }
            };
            Console.WriteLine($"way 3  row1 = {string.Join(" ", wayThree[1])}");




            Console.WriteLine();
            Console.WriteLine("=== 2. The null trap ===");

            int[][] halfBuilt = new int[2][];
            halfBuilt[0] = new int[] { 1, 2 };

            Console.WriteLine($"halfBuilt[0].Length -> {halfBuilt[0].Length}");
            Console.WriteLine($"halfBuilt[1] is null -> {halfBuilt[1] == null}");
            Console.WriteLine("halfBuilt[1].Length would throw NullReferenceException - a row you never created is null.");

            Console.WriteLine();
            Console.WriteLine("=== 3. Jagged vs 2D - the syntax ===");

            int[,] grid = new int[3, 4];
            grid[1, 2] = 7;

            Console.WriteLine($"2D     grid[1, 2] = {grid[1, 2]}    one pair of brackets, GetLength(0)={grid.GetLength(0)}, Rank={grid.Rank}");
            Console.WriteLine($"Jagged wayTwo[1][0] = {wayTwo[1][0]}   two pairs of brackets, rows={wayTwo.Length}, Rank={wayTwo.Rank}");
            Console.WriteLine("A 2D array is one block on the Heap. A jagged array is an outer array of references.");

            Console.WriteLine();
            Console.WriteLine("=== 4. Row lengths and sums ===");

            JaggedTasks.PrintRows(wayThree);

            Console.WriteLine();
            Console.WriteLine("=== 5. The real use case: marks per student ===");

            string[] names = { "Ahmed", "Sara", "Omar" };
            int[][] marks =
            {
                new int[] { 80, 90, 70 },
                new int[] { 95, 85 },
                new int[] { 60, 75, 88, 91 }
            };

            JaggedTasks.PrintAverages(names, marks);
            Console.WriteLine($"Top: {JaggedTasks.TopStudent(names, marks)}");
            Console.WriteLine();
            Console.WriteLine("Different students have different numbers of subjects -");
            Console.WriteLine("that is precisely what a 2D array cannot represent.");
        }
    }
}
