// ======================================================================
// Q2 - AGGREGATION  (weak HAS-A)
//
// The parts are created OUTSIDE and passed in. They existed before the
// whole and they keep existing after it. Close the department, the
// employees are still there.
// ======================================================================

public class Employee
{
    public string Name { get; set; }

    public Employee(string name)
    {
        Name = name;
    }
}

public class Department
{
    public string Title { get; set; }

    // Held, not owned.
    public Employee[] Staff { get; private set; }

    public Department(string title, Employee[] staff)
    {
        Title = title;
        Staff = staff;      // just a reference - no new Employee anywhere
    }

    public string StaffNames()
    {
        string result = string.Empty;

        foreach (Employee employee in Staff)
        {
            if (result.Length > 0)
            {
                result += ", ";
            }

            result += employee.Name;
        }

        return result;
    }
}
