// ======================================================================
// Q1 - ASSOCIATION  (KNOWS-A)
//
// Neither class creates the other. Both objects are built outside and
// then simply linked. Delete one and the other is still a valid object.
// ======================================================================

public class Patient
{
    public string Name { get; set; }

    // The patient only KNOWS its doctor - it never creates one.
    public Doctor? TreatedBy { get; set; }

    public Patient(string name)
    {
        Name = name;
    }
}

public class Doctor
{
    private int _count;

    public string Name { get; set; }

    public Patient[] Patients { get; private set; }

    public Doctor(string name, int capacity)
    {
        Name = name;
        Patients = new Patient[capacity];
        _count = 0;
    }

    /// <summary>Links the two objects together - in BOTH directions.</summary>
    public void Treat(Patient patient)
    {
        if (_count >= Patients.Length)
        {
            return;
        }

        Patients[_count] = patient;
        _count++;

        patient.TreatedBy = this;   // forget this line and the two sides disagree
    }

    public string PatientNames()
    {
        string result = string.Empty;

        for (int i = 0; i < _count; i++)
        {
            if (result.Length > 0)
            {
                result += ", ";
            }

            result += Patients[i].Name;
        }

        return result;
    }
}
