        _count++;

        patient.TreatedBy = this;   // forget this line and the two sides disagree
    }

    public string PatientNames()
    {
        string result = string.Empty;

        for (int i = 0; i < _count; i++)
        {
            if (result.Length > 0)
            {
                result += ", ";
            }

            result += Patients[i].Name;
        }

        return result;
    }
