[Workshop05Demo/ThreadingLib/Sync/DeadlockLab.cs] using System;
using System.Threading;

namespace ThreadingLib.Sync
{
    /// <summary>
    /// Model answer for Question 8.
    ///
    /// The reversed version really would hang forever with a plain nested lock.
    /// Monitor.TryEnter with a timeout turns the freeze into a printed message,
    /// so the program can report the deadlock instead of becoming it.
    /// </summary>
    public static class DeadlockLab
    {
        private static readonly object _lockA = new object();
        private static readonly object _lockB = new object();

        // ------------------------------------------------------------------
        // The bug: the two threads take the SAME two locks in OPPOSITE order.
        // ------------------------------------------------------------------
        public static void RunReversedOrder()
        {
            Thread t1 = new Thread(() => TakeTwo("Thread 1", _lockA, "A", _lockB, "B"));
            Thread t2 = new Thread(() => TakeTwo("Thread 2", _lockB, "B", _lockA, "A"));

            t1.Start();
            t2.Start();

            t1.Join();
            t2.Join();
        }

        // ------------------------------------------------------------------
        // The fix: BOTH threads take A first and B second. One rule, no deadlock.
        // ------------------------------------------------------------------
        public static void RunSameOrder()
        {
            Thread t1 = new Thread(() => TakeInOrder("Thread 1"));
            Thread t2 = new Thread(() => TakeInOrder("Thread 2"));

            t1.Start();
            t2.Start();

            t1.Join();
            t2.Join();
        }

        private static void TakeTwo(string who, object first, string firstName, object second, string secondName)
        {
            lock (first)
            {
                Console.WriteLine($"{who}: got {firstName}, waiting for {secondName}");

                Thread.Sleep(200);   // long enough for the other thread to grab its own lock

                if (Monitor.TryEnter(second, 1000))
                {
                    try
                    {
                        Console.WriteLine($"{who}: got {firstName}, got {secondName}, done");
                    }
                    finally
                    {
                        Monitor.Exit(second);   // TryEnter means YOU release it
                    }
                }
                else
                {
                    Console.WriteLine($"{who}: could not get {secondName} -> deadlock");
                }
            }
        }

        private static void TakeInOrder(string who)
        {
            lock (_lockA)
            {
                Thread.Sleep(200);

                lock (_lockB)
                {
                    Console.WriteLine($"{who}: got A, got B, done");
                }
            }
        }
    }
}

[Workshop05Demo/ThreadingLib/Sync/RaceCounter.cs] using System;
using System.Threading;

namespace ThreadingLib.Sync
{
    /// <summary>
    /// Model answers for Questions 6 and 7.
    ///
    /// The same 2 x 1,000,000 increments, run three ways.
    /// Only the first one is wrong - and it is wrong differently every time.
    /// </summary>
    public static class RaceCounter
    {
        public const int Iterations = 1_000_000;
        public const int ThreadCount = 2;

        public static int Expected
        {
            get { return Iterations * ThreadCount; }
        }

        // A private object used for NOTHING else. Never lock(this) or lock a string.
        private static readonly object _gate = new object();

        private static int _count;

        // ------------------------------------------------------------------
        // Q6 - no protection at all. count++ is read, add, write:
        //      three steps, two windows for another thread to cut in.
        // ------------------------------------------------------------------
        public static int RunUnprotected()
        {
            _count = 0;

            RunOnTwoThreads(() =>
            {
                for (int i = 0; i < Iterations; i++)
                {
                    _count++;              // NOT atomic
                }
            });

            return _count;
        }

        // ------------------------------------------------------------------
        // Q7a - lock: one thread inside the braces at a time.
        // ------------------------------------------------------------------
        public static int RunWithLock()
        {
            _count = 0;

            RunOnTwoThreads(() =>
            {
                for (int i = 0; i < Iterations; i++)
                {
                    lock (_gate)
                    {
                        _count++;
                    }
                }
            });

            return _count;
        }

        // ------------------------------------------------------------------
        // Q7b - Interlocked: the whole read-add-write becomes one CPU
        //       instruction, so there is no window to cut into at all.
        // ------------------------------------------------------------------
        public static int RunWithInterlocked()
        {
            _count = 0;

            RunOnTwoThreads(() =>
            {
                for (int i = 0; i < Iterations; i++)
                {
                    Interlocked.Increment(ref _count);
                }
            });

            return _count;
        }

        private static void RunOnTwoThreads(ThreadStart body)
        {
            Thread[] workers = new Thread[ThreadCount];

            for (int i = 0; i < ThreadCount; i++)
            {
                workers[i] = new Thread(body);
                workers[i].Start();
            }

            foreach (Thread worker in workers)
            {
                worker.Join();
            }
        }
    }
}

