[Workshop05Demo/Workshop05.ConsoleApp/Demos/BackgroundAndPoolDemo.cs] using System;
using System.Diagnostics;
using System.Threading;
using ThreadingLib.Background;

namespace Workshop05.ConsoleApp.Demos
{
    /// <summary>Live demo for the slides "Foreground vs Background" and "Thread Pool".</summary>
    public static class BackgroundAndPoolDemo
    {
        public static void Run()
        {
            Console.WriteLine("=== 1. Foreground is the default ===");

            Thread foreground = new Thread(() => Thread.Sleep(100));

            Console.WriteLine($"a brand new thread: IsBackground -> {foreground.IsBackground}");
            Console.WriteLine("So the process will wait for it, whether you Join or not.");

            Console.WriteLine();
            Console.WriteLine("=== 2. The switch must be flipped BEFORE Start() ===");

            Thread background = new Thread(() => Thread.Sleep(100));
            background.IsBackground = true;
            background.Start();
            background.Join();

            Console.WriteLine("background.IsBackground = true;  <- before Start(), never after");
            Console.WriteLine();
            Console.WriteLine("The real difference only appears when Main RETURNS, so run these:");
            Console.WriteLine("   dotnet run --project Workshop05.ConsoleApp -- q4-foreground");
            Console.WriteLine("   dotnet run --project Workshop05.ConsoleApp -- q4-background");
            Console.WriteLine("The first prints three Worker lines. The second prints none.");

            Console.WriteLine();
            Console.WriteLine("=== 3. Every pool thread is a background thread ===");

            Console.WriteLine($"checked from inside a queued item -> {PoolTasks.PoolThreadsAreBackground()}");
            Console.WriteLine("That is why queued work can vanish silently when an app closes.");

            Console.WriteLine();
            Console.WriteLine("=== 4. Queue work and wait for all of it ===");

            int[] squares = PoolTasks.SquaresOnPool(5);

            Console.WriteLine($"squares -> {string.Join(" ", squares)}");
            Console.WriteLine("CountdownEvent(5) + one Signal() per item + Wait() in Main.");
            Console.WriteLine("Drop the Wait() and you usually print an empty array.");

            Console.WriteLine();
            Console.WriteLine("=== 5. Why the pool exists at all ===");

            Stopwatch watch = Stopwatch.StartNew();

            for (int i = 0; i < 200; i++)
            {
                Thread t = new Thread(() => { });
                t.Start();
                t.Join();
            }

            watch.Stop();
            long ownThreads = watch.ElapsedMilliseconds;

            watch.Restart();

            using (CountdownEvent done = new CountdownEvent(200))
            {
                for (int i = 0; i < 200; i++)
                {
                    ThreadPool.QueueUserWorkItem(state => done.Signal());
                }

                done.Wait();
            }

            watch.Stop();

            Console.WriteLine($"200 new threads  -> {ownThreads} ms");
            Console.WriteLine($"200 pool items   -> {watch.ElapsedMilliseconds} ms");
            Console.WriteLine("The pool already has its threads warmed up. You are only queuing work.");
        }
    }
}

[Workshop05Demo/Workshop05.ConsoleApp/Demos/SynchronizationDemo.cs] using System;
using System.Diagnostics;
using ThreadingLib.Sync;

namespace Workshop05.ConsoleApp.Demos
{
    /// <summary>Live demo for the slides "Race Condition", "lock", "lock vs Interlocked" and "Deadlock".</summary>
    public static class SynchronizationDemo
    {
        public static void Run()
        {
            Console.WriteLine("=== 1. count++ is three steps, not one ===");
            Console.WriteLine("   READ   load count into a register");
            Console.WriteLine("   ADD    add 1 inside the register");
            Console.WriteLine("   WRITE  store it back to memory");
            Console.WriteLine("Three steps means two windows where another thread can cut in.");

            Console.WriteLine();
            Console.WriteLine("=== 2. Watch the updates disappear ===");
            Console.WriteLine($"expected every time: {RaceCounter.Expected}");

            for (int run = 1; run <= 3; run++)
            {
                int actual = RaceCounter.RunUnprotected();
                Console.WriteLine($"   run {run} -> {actual,10}   lost {RaceCounter.Expected - actual}");
            }

            Console.WriteLine("Nothing here is random. The threads simply overlapped somewhere different.");

            Console.WriteLine();
            Console.WriteLine("=== 3. Two ways to fix it ===");

            Stopwatch watch = Stopwatch.StartNew();
            int withLock = RaceCounter.RunWithLock();
            watch.Stop();
            long lockMs = watch.ElapsedMilliseconds;

            watch.Restart();
            int withInterlocked = RaceCounter.RunWithInterlocked();
            watch.Stop();

            Console.WriteLine($"lock        -> {withLock}   in {lockMs} ms");
            Console.WriteLine($"Interlocked -> {withInterlocked}   in {watch.ElapsedMilliseconds} ms");
            Console.WriteLine();
            Console.WriteLine("Both are correct. Interlocked wins here because the whole critical");
            Console.WriteLine("section is one counter - it becomes a single CPU instruction.");
            Console.WriteLine("The moment you need two lines protected together, go back to lock.");

            Console.WriteLine();
