        // ------------------------------------------------------------------
        public static void RunWithJoin(string workerName)
        {
            EnsureMainIsNamed();

            Thread worker = new Thread(() =>
            {
                Thread.Sleep(300);
                Console.WriteLine($"{Thread.CurrentThread.Name} running");
            });

            worker.Name = workerName;             // set BEFORE Start()
            worker.Start();

            Console.WriteLine($"Main thread name  : {Thread.CurrentThread.Name}");
            Console.WriteLine($"IsAlive after Start: {worker.IsAlive}");

            worker.Join();                        // block Main until the worker ends

            Console.WriteLine($"IsAlive after Join : {worker.IsAlive}");
            Console.WriteLine("Main finished");
        }

        /// <summary>
        /// Example 2 of Q1: exactly the same method with the Join() line removed.
        /// Main reaches the end first, and the worker prints afterwards -
        /// the process stays alive because a FOREGROUND thread is still running.
        /// </summary>
        public static void RunWithoutJoin(string workerName)
        {
            EnsureMainIsNamed();

            Thread worker = new Thread(() =>
            {
                Thread.Sleep(300);
                Console.WriteLine($"{Thread.CurrentThread.Name} running");
            });

            worker.Name = workerName;
            worker.Start();

            Console.WriteLine($"Main thread name  : {Thread.CurrentThread.Name}");
            Console.WriteLine($"IsAlive after Start: {worker.IsAlive}");
            Console.WriteLine($"IsAlive after Join : {worker.IsAlive}");
            Console.WriteLine("Main finished");

            // Only so the menu app stays tidy - a real Main would simply return here
            // and the worker line would still appear, because it is a foreground thread.
            worker.Join();
        }

        /// <summary>
        /// Treat Thread.Name as write-once: set it, then leave it alone.
        /// The null check also lets this method be called twice from the menu
        /// without fighting the runtime over a name that is already there.
        /// </summary>
        private static void EnsureMainIsNamed()
        {
            if (Thread.CurrentThread.Name == null)
