using System.Threading;

namespace ThreadingLib.Sync
{
    /// <summary>
    /// Model answers for Questions 6 and 7.
    ///
    /// The same 2 x 1,000,000 increments, run three ways.
    /// Only the first one is wrong - and it is wrong differently every time.
    /// </summary>
    public static class RaceCounter
    {
        public const int Iterations = 1_000_000;
        public const int ThreadCount = 2;

        public static int Expected
        {
            get { return Iterations * ThreadCount; }
        }

        // A private object used for NOTHING else. Never lock(this) or lock a string.
        private static readonly object _gate = new object();

        private static int _count;

        // ------------------------------------------------------------------
        // Q6 - no protection at all. count++ is read, add, write:
        //      three steps, two windows for another thread to cut in.
        // ------------------------------------------------------------------
        public static int RunUnprotected()
        {
            _count = 0;

            RunOnTwoThreads(() =>
            {
                for (int i = 0; i < Iterations; i++)
                {
                    _count++;              // NOT atomic
                }
            });

            return _count;
        }

        // ------------------------------------------------------------------
        // Q7a - lock: one thread inside the braces at a time.
        // ------------------------------------------------------------------
        public static int RunWithLock()
        {
            _count = 0;

            RunOnTwoThreads(() =>
            {
                for (int i = 0; i < Iterations; i++)
                {
                    lock (_gate)
                    {
                        _count++;
                    }
                }
            });

            return _count;
        }

        // ------------------------------------------------------------------
        // Q7b - Interlocked: the whole read-add-write becomes one CPU
        //       instruction, so there is no window to cut into at all.
        // ------------------------------------------------------------------
        public static int RunWithInterlocked()
        {
            _count = 0;

            RunOnTwoThreads(() =>
            {
                for (int i = 0; i < Iterations; i++)
                {
                    Interlocked.Increment(ref _count);
                }
            });

            return _count;
        }

        private static void RunOnTwoThreads(ThreadStart body)
        {
            Thread[] workers = new Thread[ThreadCount];

            for (int i = 0; i < ThreadCount; i++)
            {
                workers[i] = new Thread(body);
                workers[i].Start();
            }

            foreach (Thread worker in workers)
            {
                worker.Join();
            }
        }
    }
}
