namespace Workshop05.ConsoleApp.Demos
{
    /// <summary>Live demo for the slides "Creating a Thread", "The Thread Object" and "Join and Sleep".</summary>
    public static class ThreadBasicsDemo
    {
        public static void Run()
        {
            Console.WriteLine("=== 1. Who am I running on? ===");

            Thread main = Thread.CurrentThread;

            Console.WriteLine($"ManagedThreadId -> {main.ManagedThreadId}");
            Console.WriteLine($"IsBackground    -> {main.IsBackground}");
            Console.WriteLine($"IsThreadPool    -> {main.IsThreadPoolThread}");
            Console.WriteLine("This is the thread the CLR started your app on.");

            Console.WriteLine();
            Console.WriteLine("=== 2. Four ways to give a thread its work ===");

            Thread t1 = new Thread(SayHello);
            Thread t2 = new Thread(() => Console.WriteLine("   2 - from a lambda"));

            Thread t3 = new Thread(new ParameterizedThreadStart(SayNumber));

            int captured = 42;
            Thread t4 = new Thread(() => Console.WriteLine($"   4 - captured local = {captured}"));

            t1.Start();
            t1.Join();
            t2.Start();
            t2.Join();
            t3.Start(7);                 // the argument goes into Start
            t3.Join();
            t4.Start();
            t4.Join();

            Console.WriteLine("new Thread(...) creates nothing. Start() is what asks the OS for a thread.");

            Console.WriteLine();
            Console.WriteLine("=== 3. The classic capture bug ===");

            Console.WriteLine("   sharing the loop variable:");
            Thread[] bad = new Thread[3];

            for (int i = 0; i < 3; i++)
            {
                bad[i] = new Thread(() => Console.Write($" {i}"));
            }

            foreach (Thread t in bad) { t.Start(); t.Join(); }
            Console.WriteLine("     <- all three usually print 3");

            Console.WriteLine("   copying it into a local:");
            Thread[] good = new Thread[3];

            for (int i = 0; i < 3; i++)
            {
                int copy = i;
                good[i] = new Thread(() => Console.Write($" {copy}"));
            }

            foreach (Thread t in good) { t.Start(); t.Join(); }
            Console.WriteLine("     <- 0 1 2, as intended");

            Console.WriteLine();
            Console.WriteLine("=== 4. IsAlive and ThreadState ===");

            Thread sleeper = new Thread(() => Thread.Sleep(400));

            Console.WriteLine($"before Start -> IsAlive={sleeper.IsAlive}, state={sleeper.ThreadState}");
            sleeper.Start();
            Thread.Sleep(100);
            Console.WriteLine($"while running-> IsAlive={sleeper.IsAlive}, state={sleeper.ThreadState}");
            sleeper.Join();
            Console.WriteLine($"after Join   -> IsAlive={sleeper.IsAlive}, state={sleeper.ThreadState}");

            Console.WriteLine();
            Console.WriteLine("=== 5. Join makes the LAST line deterministic ===");

            Thread[] workers = new Thread[3];

            for (int i = 0; i < workers.Length; i++)
            {
                int copy = i;

                workers[i] = new Thread(() =>
                {
                    Thread.Sleep(200);
                    Console.WriteLine($"   Worker {copy} done");
                });

                workers[i].Start();
            }

            foreach (Thread w in workers)
            {
                w.Join();
            }

            Console.WriteLine("All workers finished");
            Console.WriteLine("The three Worker lines can come out in any order. This one cannot.");
        }

        private static void SayHello()
        {
            Console.WriteLine("   1 - from a method");
        }

