using EFCoreDay01.Context;
using EFCoreDay01.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Threading.Tasks;

namespace EFCoreDay01.Seeds
{
    internal static class MyDbContextSeeding
    {

            public static bool AuthorsSeeding(MyDbContext dbContext)
            {
                try
                {
                // Steps:
                // 0. Check if Authors empty
                // 1. Read the JSON file [as string].
                // 2. Convert JSON data into a List of Author objects.
                // 3. Add the Authors to the database.
                // 4. Save changes.

                // Check if Authors already exist
                if (dbContext.Authers.Any()) return false;

                    // Read data from JSON file (String Format)
                    var authorsData = File.ReadAllText("Files/Authors.json");

                    if (string.IsNullOrWhiteSpace(authorsData)) return false;

                    // Convert JSON data into a List of Author objects
                    var authors = JsonSerializer.Deserialize<List<Auther>>(
                        authorsData,
                        new JsonSerializerOptions { PropertyNameCaseInsensitive = true }
                    );

                    if (authors is null || authors.Count == 0)
                        return false;

                    // Add Authors to the database
                    dbContext.Authers.AddRange(authors);

                    // Save changes to the database
                    return dbContext.SaveChanges() > 0;
                }
                catch (Exception ex)
                {
                    Console.WriteLine(ex.Message);
                    return false;
                }
            }

            public static bool DataSeeding<T>(MyDbContext dbContext, DbSet<T> dbSet, string fileName) where T : class
            {
                try
                {
                    // Steps:
                    // 1. Read the JSON file.
                    // 2. Convert JSON data into a List of objects of type T.
                    // 3. Add the objects to the corresponding DbSet.
                    // 4. Save changes.
              
                    // Check if data already exists
                    if (dbSet.Any()) return false;
              
                    // Read data from JSON file (String Format)
                    var dataFromFile = File.ReadAllText($"Files\\{fileName}");
              
                    if (string.IsNullOrWhiteSpace(dataFromFile)) return false;

                // Convert JSON data into a List of objects of type T
                //var options = new JsonSerializerOptions
                //{
                //    PropertyNameCaseInsensitive = true,
                //    Converters = { new JsonStringEnumConverter() }
                //};

                var data = JsonSerializer.Deserialize<List<T>>(
                    dataFromFile,
                    new JsonSerializerOptions
                    {
                        PropertyNameCaseInsensitive = true,
                        Converters = { new JsonStringEnumConverter() }
                    }
                );

                if (data is null || data.Count == 0)
                        return false;
              
                    // Add objects to the corresponding DbSet
                    dbSet.AddRange(data);
              
                    // Save changes to the database
                    return dbContext.SaveChanges() > 0;
                }
                catch (Exception ex)
                {
                    Console.WriteLine(ex.Message);
                    return false;
                }
        }


    }
    }

