using EFCoreDay01.Context;
using EFCoreDay01.Enums;
using EFCoreDay01.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace EFCoreDay01.Operations
{
    internal class LoanManager
    {


        //Member Exits, Memebr status=Acitve
        //Book Exits,AvailableCopies
        //Creare loan
        //MemberBookloan(LoanId, MemberId, BookId)
        // Add Memberloan
        // Book AvailableCopies -1
        public static bool BorrowingBook(int MemberId, int BookId, int BorrowingDays, MyDbContext dbContext)
        {
            using var Transaction = dbContext.Database.BeginTransaction();
            try
            {
                // Member Exits , Memebr status=Acitve 
                var member = dbContext.Members.Find(MemberId);
                if (member == null || member.Status == MemberStatus.Suspended) return false;

                // Book Exits,AvailableCopies 
                var book = dbContext.Books.Find(BookId);
                if (book == null || book.AvaliableCopies == 0) return false;

                // Create loan
                var loan = new Loan();
                dbContext.Loans.Add(loan);

                // Member loan (LoanId,MemberId,BookId)
                var memberLoan = new MemberBookLoan
                {
                    BookId = BookId,
                    MemberId = MemberId,
                    Loan = loan,
                    DueDate = DateTime.Now.AddDays(BorrowingDays)
                };

                // Add Memberloan
                dbContext.MemberBookLoans.Add(memberLoan);

                // Book AvailableCopies -1
                book.AvaliableCopies -= 1;
                dbContext.SaveChanges();
                Transaction.Commit();
                return true;
            }
            catch (Exception ex)
            {

                Console.WriteLine(ex);
                Transaction.Rollback();
                return false;
            }
        }

        // Return Member loan (MemberId,BookId,ReturnDate=null)
        //Check Member loan 
        // Set RetrunDate
        // Book AvailableCopies +1
        // calaucte fine if needed (return data > due date )
        // change status of loan 
        // change status of member from acitve to suspended


        public static bool RetrunBook(int MemberId, int BookId, MyDbContext dbContext)
        {

            // Return Member loan (MemberId,BookId,ReturnDate=null)
            var memberLoan = dbContext.MemberBookLoans
                .Include(X => X.Loan)
                .Include(X => X.Book)
                .FirstOrDefault(X => X.MemberId == MemberId && X.BookId == BookId && X.ReturnDate == null);
            //Check Member loan 
            if (memberLoan is null) return false;
            // Set RetrunDate
            memberLoan.ReturnDate = DateTime.Now;
            // Book AvailableCopies +1
            memberLoan.Book.AvaliableCopies += 1;

            // calaucte fine if needed 
            if (memberLoan.ReturnDate.Value.Date > memberLoan.DueDate.Date)
            {
                var overDueDays =(memberLoan.ReturnDate.Value.Date - memberLoan.DueDate.Date).Days;
          
                
                var fine = new Fine()
                {
                    Amount = overDueDays * 0.1M * memberLoan.Book.Price,
                    Loan = memberLoan.Loan
                };
                dbContext.Fines.Add(fine);
                // change status of loan retruen => overdue 
                memberLoan.Loan.Status = LoanStatus.Overdue;
                // change status of member from acitve to suspended
                var member = dbContext.Members.FirstOrDefault(X => X.Id == memberLoan.MemberId);
                member.Status = MemberStatus.Suspended;
            }
            else
            {
                memberLoan.Loan.Status = LoanStatus.Returned;
            }
            dbContext.SaveChanges();
            return true;

        }




    }
}

