using System.Threading.Tasks;

namespace EFCoreDay01.Operations
{
    internal class Search
    {
        // connect to the database to reach the books table 
        // use context to access the database and use LINQ to query the books table

        public static void SearchBooks(MyDbContext context)
        {

            Console.Write("Enter book title, author, or category: ");
            string searchText = Console.ReadLine();

            if (string.IsNullOrWhiteSpace(searchText))
            {
                Console.WriteLine("Search text cannot be empty.");
                return;
            }

            var books = context.Books.Where(b => b.Title == searchText ||
                 b.BookAuthor.FirstName == searchText ||
                 b.BookCategory.Title == searchText);

            foreach (var book in books)
            {
                Console.WriteLine($"ID: {book.Id}");
                Console.WriteLine($"Title: {book.Title}");
                Console.WriteLine("-------------------------");
            }
        }
    }
}

