    internal class Book  //[No Need To Make it Public]
    {
        // numeric prop named Id or ClassNameId will be considered as PK and Identity(1,1)
        public int Id { get; set; }
        // by default string prop will be mapped to NVarchar(max) and Not Nullable [Mandatory]
