            modelBuilder.Entity<Book>().HasKey(b => b.Id);
            modelBuilder.Entity<Book>().Property(b => b.Title).HasColumnType("varchar(50)");
            modelBuilder.Entity<Book>().Property(b => b.Price).HasColumnType("decimal(6,2)");
            modelBuilder.Entity<Book>().ToTable("Books").HasCheckConstraint("CK_Book_PublicationYear", "PublicationYear BETWEEN 1950 AND 2026");
            modelBuilder.Entity<Book>().ToTable("Books").HasCheckConstraint("CH_Book_AvaliableCopies", "AvaliableCopies<=TotalCopies");

            modelBuilder.Entity<Book>(B =>
            {
                B.HasKey(b => b.Id);
                B.Property(b => b.Title).HasColumnType("varchar(50)");
                B.Property(b => b.Price).HasColumnType("decimal(6,2)");
                B.ToTable("Books", B =>
                {
                    B.HasCheckConstraint("CK_Book_PublicationYear", "PublicationYear BETWEEN 1950 AND 2026");
