using LibrarySystem.Configurations;
using LibrarySystem.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading.Tasks;

namespace LibrarySystem.Context
{
    // install package efcore.sqlserver
    internal class MyDBContext : DbContext
    {

        #region Connect Database [overrride Oncongiguring]

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {

            optionsBuilder.UseSqlServer("Server = . ; Database = LibrarySystem ; Trusted_Connection = true ; Encrypt = false");

        }

        #endregion
        // to reach migartion we have to install package .tools
        // Update-database -> create object MyDBContext , obj.migrate()
        //  obj.migrate() -->> applying all pending migrations

        #region Dbsets
        public DbSet<Book> Books { get; set; }
        public DbSet<Category>  Categories{ get; set; }
        public DbSet<Author>  Authors { get; set; }
        public DbSet<Member> Members { get; set; }
        public DbSet<Loan> Loans { get; set; }
        public DbSet<Fine> Fines { get; set; }
        public DbSet<MemberBookLoan> memberBookLoans{ get; set; }





        #endregion

        // Fluent Apis [Override OnModelCreating] 
        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            #region Third Way FluentApis

            //modelBuilder.Entity<Book>().HasKey(B => B.Id);
            //modelBuilder.Entity<Book>().Property(B => B.Title).HasColumnType("varchar(50)");
            //modelBuilder.Entity<Book>().Property(B => B.Price).HasColumnType("decimal(6,2)");
            //modelBuilder.Entity<Book>().ToTable("Books").HasCheckConstraint("CH-Book-PublicationYear", "PublicationYear between 1950 and Year(Getdate())");
            //modelBuilder.Entity<Book>().ToTable("Books").HasCheckConstraint("CH-Book-AvailableBooks", "AvailableCopies <= TotalCopies");


            modelBuilder.Entity<Book>(B =>
            {
                B.HasKey(B => B.Id);
                B.Property(B => B.Title).HasColumnType("varchar(50)");
                B.Property(B => B.Price).HasColumnType("decimal(6,2)");
                B.ToTable("Books", B =>
                {
                    B.HasCheckConstraint("CH-Book-PublicationYear", "PublicationYear between 1950 and Year(Getdate())");
                    B.HasCheckConstraint("CH-Book-AvailableBooks", "AvailableCopies <= TotalCopies");
                });
            });

            #endregion

            #region Fourth Way [Class Configurations]
            // Compiler Can Detect The type Of Entity [Input Parameter]

            //modelBuilder.ApplyConfiguration/*<Member>*/(new MemberConfiguration());
            //modelBuilder.ApplyConfiguration/*<Member>*/(new BookConfiguration());
            //modelBuilder.ApplyConfiguration/*<Member>*/(new LoanConfiguration());

            modelBuilder.ApplyConfigurationsFromAssembly(Assembly.GetExecutingAssembly());
            // Efcore Apply All Configuration Of All Classes Implement interface IEntityTypeConfiguration







            #endregion


        }



    }
}

