using LibrarySystem.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace LibrarySystem.Configurations
{
    internal class MemberConfiguration : IEntityTypeConfiguration<Member>
    {
        public void Configure(EntityTypeBuilder<Member> builder)
        {
            
            builder.HasKey(x => x.Id);
            builder.Property(m => m.Id).UseIdentityColumn(10,10);
            builder.Property(m => m.Name).HasColumnType("varchar(50)");
            builder.Property(m => m.Email).HasColumnType("varchar(100)");
            builder.Property(m => m.PhoneNumber).HasColumnType("varchar(11)");
            builder.Property(m => m.Address).HasColumnType("varchar(100)");
            builder.Property(m => m.MemberShipDate).HasDefaultValueSql("GetDate()");
            builder.Property(m => m.MemberStatus).HasConversion<string>();

            builder.ToTable("Members", m =>
            {
                m.HasCheckConstraint("CH-Member-PhoneNumber", "LEN(PhoneNumber)= 11 and PhoneNumber like '01[0125][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' ");
                //m.HasCheckConstraint("CH-Member-PhoneNumber", "LEN(PhoneNumber)= 11 and PhoneNumber like '01[0125]%' and PhoneNumber not like '%[^0-9]%'");

                m.HasCheckConstraint("CH-Member-Email", "Email not like '% %' and Email like '_%@_%._%'");
            });



        }
    }
}
